CREATE OR REPLACE FUNCTION public.approve_customer_branch_repair_v14(p_customer_code text, p_reviewed_by text DEFAULT 'app'::text)
 RETURNS TABLE(ok boolean, message text, old_branch text, new_branch text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_new text;
  v_old text;
  v_updated int := 0;
begin
  v_new := public.dawaa_best_customer_branch(p_customer_code);

  if v_new is null then
    select suggested_branch into v_new
    from public.dawaa_customer_branch_review_queue_v14
    where customer_code::text = p_customer_code
    limit 1;
  end if;

  if v_new is null or trim(v_new) = '' then
    return query select false, 'لا يوجد فرع مقترح لهذا العميل', null::text, null::text;
    return;
  end if;

  if to_regclass('public.customers') is not null then
    execute 'select branch::text from public.customers where customer_code::text = $1 or code::text = $1 limit 1'
      into v_old using p_customer_code;
    execute 'update public.customers set branch = $1 where customer_code::text = $2 or code::text = $2'
      using v_new, p_customer_code;
    get diagnostics v_updated = row_count;
  end if;

  if v_updated = 0 and to_regclass('public.customer_analysis') is not null then
    execute 'update public.customer_analysis set branch = $1 where customer_code::text = $2 or code::text = $2'
      using v_new, p_customer_code;
    get diagnostics v_updated = row_count;
  end if;

  insert into public.dawaa_customer_repair_log(repair_type, customer_code, old_value, new_value, reviewed_by, note)
  values ('branch_approved', p_customer_code, v_old, v_new, p_reviewed_by, 'اعتماد تصحيح الفرع من التطبيق');

  return query select true, 'تم اعتماد تصحيح الفرع', v_old, v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.dawaa_apply_basic_rls_policy_v2(p_table_name text, p_admin_all boolean DEFAULT true, p_auth_select boolean DEFAULT true, p_auth_insert boolean DEFAULT true, p_auth_update boolean DEFAULT true)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_table regclass;
  v_policy_prefix text;
begin
  v_table := to_regclass('public.' || quote_ident(p_table_name));

  if v_table is null then
    return 'SKIPPED: public.' || p_table_name || ' does not exist';
  end if;

  v_policy_prefix := regexp_replace(p_table_name, '[^a-zA-Z0-9_]+', '_', 'g');

  execute format('alter table public.%I enable row level security', p_table_name);

  execute format('drop policy if exists "%s_admin_all" on public.%I', v_policy_prefix, p_table_name);
  execute format('drop policy if exists "%s_auth_select" on public.%I', v_policy_prefix, p_table_name);
  execute format('drop policy if exists "%s_auth_insert" on public.%I', v_policy_prefix, p_table_name);
  execute format('drop policy if exists "%s_auth_update" on public.%I', v_policy_prefix, p_table_name);
  execute format('drop policy if exists "Allow app access %s" on public.%I', p_table_name, p_table_name);

  if p_admin_all then
    execute format(
      'create policy "%s_admin_all" on public.%I for all to authenticated using (public.is_app_admin()) with check (public.is_app_admin())',
      v_policy_prefix,
      p_table_name
    );
  end if;

  if p_auth_select then
    execute format(
      'create policy "%s_auth_select" on public.%I for select to authenticated using (true)',
      v_policy_prefix,
      p_table_name
    );
  end if;

  if p_auth_insert then
    execute format(
      'create policy "%s_auth_insert" on public.%I for insert to authenticated with check (true)',
      v_policy_prefix,
      p_table_name
    );
  end if;

  if p_auth_update then
    execute format(
      'create policy "%s_auth_update" on public.%I for update to authenticated using (true) with check (true)',
      v_policy_prefix,
      p_table_name
    );
  end if;

  return 'OK: public.' || p_table_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_dashboard_customer_service_summary_v18(p_branch text DEFAULT 'كل الفروع'::text)
 RETURNS TABLE(open_followups bigint, completed_today bigint, needs_manager bigint, avg_response_hours numeric, unregistered_customer_invoices bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_open bigint := 0;
  v_completed bigint := 0;
  v_manager bigint := 0;
begin
  if to_regclass('public.dawaa_customer_service_current_queue_v14') is not null then
    execute 'select count(*)::bigint from public.dawaa_customer_service_current_queue_v14 where ($1 = ''كل الفروع'' or coalesce(branch::text, '''') = $1)'
    using coalesce(p_branch,'كل الفروع') into v_open;
  elsif to_regclass('public.daily_followups') is not null then
    execute 'select count(*)::bigint from public.daily_followups where coalesce(status,'''') not in (''تم'',''تم التواصل'',''منتهي'',''مكتمل'',''closed'',''completed'',''done'')'
    into v_open;
  end if;

  if to_regclass('public.daily_followups') is not null then
    execute 'select count(*)::bigint from public.daily_followups where status = ''تم'' and updated_at >= current_date'
    into v_completed;
    execute 'select count(*)::bigint from public.daily_followups where status ilike ''%مدير%'''
    into v_manager;
  end if;

  return query select v_open, v_completed, v_manager, null::numeric, 0::bigint;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_dashboard_staff_ops_summary_v18()
 RETURNS TABLE(active_accounts bigint, disabled_accounts bigint, pending_time_off bigint, absences_today bigint, late_today bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_active bigint := 0;
  v_disabled bigint := 0;
begin
  if to_regclass('public.staff_accounts') is not null then
    execute 'select count(*)::bigint from public.staff_accounts where active = true and coalesce(can_login,true) = true' into v_active;
    execute 'select count(*)::bigint from public.staff_accounts where active = false or coalesce(can_login,true) = false' into v_disabled;
  end if;
  return query select v_active, v_disabled, 0::bigint, 0::bigint, 0::bigint;
end;
$function$

CREATE OR REPLACE FUNCTION public.my_workforce_snapshot_v1(p_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_staff_id uuid;
  v_date date:=coalesce(p_date,(now() at time zone 'Africa/Cairo')::date);
  v_today record;
  v_next record;
  v_pending_corrections integer:=0;
  v_pending_timeoff integer:=0;
  v_pending_ot integer:=0;
begin
  v_staff_id:=public.dawaa_current_actor_staff_id_v1();
  if v_staff_id is null then
    return jsonb_build_object('linked',false);
  end if;

  select * into v_today from public.attendance_schedule_for_date_v1(v_staff_id,v_date) limit 1;

  select x.* into v_next
  from generate_series(1,14) n
  cross join lateral public.attendance_schedule_for_date_v1(v_staff_id,v_date+n) x
  where not coalesce(x.is_off,false) and not coalesce(x.is_day_off,false)
  order by n
  limit 1;

  if to_regclass('public.attendance_correction_requests') is not null then
    execute 'select count(*)::int from public.attendance_correction_requests where staff_id=$1 and status in (''pending'',''submitted'',''review'')'
      into v_pending_corrections using v_staff_id;
  end if;

  if to_regclass('public.staff_time_off_requests') is not null then
    execute 'select count(*)::int from public.staff_time_off_requests where staff_id=$1 and status=''pending'''
      into v_pending_timeoff using v_staff_id;
  end if;

  if to_regclass('public.staff_overtime_approvals') is not null then
    select count(*)::int into v_pending_ot
    from public.staff_overtime_approvals
    where staff_id=v_staff_id and status='pending';
  end if;

  return jsonb_build_object(
    'linked',true,
    'staff_id',v_staff_id,
    'date',v_date,
    'today_schedule',case when v_today.schedule_id is null then null else jsonb_build_object(
      'schedule_id',v_today.schedule_id,'branch',v_today.branch,'day_name',v_today.day_name,
      'shift_start',v_today.shift_start,'shift_end',v_today.shift_end,'is_off',v_today.is_off,
      'is_day_off',v_today.is_day_off,'source_kind',v_today.source_kind
    ) end,
    'next_schedule',case when v_next.schedule_id is null then null else jsonb_build_object(
      'schedule_id',v_next.schedule_id,'branch',v_next.branch,'day_name',v_next.day_name,
      'shift_start',v_next.shift_start,'shift_end',v_next.shift_end,'source_kind',v_next.source_kind
    ) end,
    'pending_corrections',coalesce(v_pending_corrections,0),
    'pending_time_off',coalesce(v_pending_timeoff,0),
    'pending_overtime',coalesce(v_pending_ot,0)
  );
end;
$function$
